class Solution {
  private static long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public long minimumTime(int[] d, int[] r) {
    long lcm = (long) r[0] / gcd(r[0], r[1]) * r[1];
    long lo = 1, hi = 100_000_000_000L;
    while (lo < hi) {
      long t = lo + (hi - lo) / 2;
      long a = t - t / r[0], b = t - t / r[1], c = t - t / lcm;
      if (d[0] <= a && d[1] <= b && (long) d[0] + d[1] <= c) hi = t;
      else lo = t + 1;
    }
    return lo;
  }
}
